// Données et scénarios synthétiques, conçus pour la comparaison en classe.
const Q=(id,text,options,answer,why)=>({id,text,options,answer,why});
const T=(headers,rows,caption='Données fictives du dossier Déclic')=>`<div class="evidence-table"><table><caption>${caption}</caption><thead><tr>${headers.map(x=>`<th scope="col">${x}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(x=>`<td>${x}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
const records=Array.from({length:48},(_,i)=>({id:`D${String(i+1).padStart(3,'0')}`,atelier:['Photo','Son','Affiche'][i%3],canal:['Instagram','E-mail','Affiche','Partenaire'][Math.floor(i/3)%4],prix:[12,18,24][i%3],present:i%4===0?'Non':'Oui',attente:3+(i*7)%18}));
const sessions=[['Photo','Matin','Oui',40,32],['Photo','Matin','Non',40,28],['Photo','Soir','Oui',40,24],['Photo','Soir','Non',40,20],['Son','Matin','Oui',30,24],['Son','Matin','Non',30,21],['Son','Soir','Oui',30,18],['Son','Soir','Non',30,15],['Affiche','Matin','Oui',20,16],['Affiche','Matin','Non',20,14],['Affiche','Soir','Oui',20,12],['Affiche','Soir','Non',20,10]];
const sessionTable=()=>T(['Atelier','Créneau','Rappel reçu','Inscrits','Présents'],sessions,'Bilan agrégé : 12 groupes, 360 inscriptions à des ateliers. Un participant peut avoir plusieurs inscriptions.');
