const predictionRows=[.95,.9,.85,.8,.75,.7,.65,.6,.55,.5,.45,.4,.35,.3,.25,.2,.15,.1,.08,.05].map((score,i)=>({id:`V${i+1}`,score,absent:[0,1,2,4,6,8,10,14].includes(i)}));
const toolsState={filter:'Tous',clean:{dedup:false,channel:false,missing:false},budget:2,flow:'bilan',threshold:50,subset:'jour',groups:{}};
const steps={},responses={},checked={},validated=new Set();
const workshop={
types:[
 {title:'Ouvrir le registre',intro:'Explorez les 48 inscriptions. Filtrez par atelier, comparez les colonnes et téléchargez le registre si nécessaire. Chaque ligne est une inscription, pas une variable.',widget:'registry',hint:'Une étiquette peut contenir des chiffres. Une colonne numérique ne représente pas toujours une quantité.',questions:[
 Q('t1','D001 est-il une quantité que l’on peut additionner ?',['Oui, car il contient des chiffres','Non, c’est un identifiant'],1,'D001 sert à distinguer une inscription. Sa valeur numérique éventuelle ne mesure rien.'),
 Q('t2','Quelle variable est quantitative ?',['Le canal d’acquisition','Le nom de l’atelier','Le prix payé'],2,'Le prix est une quantité monétaire. On peut calculer un total ou une moyenne.'),
 Q('t3','Après avoir sélectionné Photo, combien de lignes restent visibles ?',['12','16','24'],1,'Les 48 inscriptions sont réparties entre trois ateliers de 16 inscriptions chacun.'),
 Q('t4','Le registre est structuré parce que…',['Il contient uniquement des nombres','Chaque ligne utilise les mêmes champs','Il contient beaucoup de lignes'],1,'Une table avec des champs réguliers est structurée, même si plusieurs colonnes sont qualitatives.') ]},
 {title:'Qualifier les sources',intro:'La communication envoie aussi des contenus qui ne rentrent pas tous dans une table. Distinguez le contenu et son enveloppe.',evidence:()=>T(['Pièce','Contenu'],[['A','Table CSV : canal, prix, atelier'],['B','Photo JPEG de la scène'],['C','Enregistrement audio d’un entretien'],['D','Objet JSON : {"atelier":"Photo","commentaire":"Très bon accueil"}'],['E','Nombre d’entrées : 243'],['F','Niveau de satisfaction : faible / moyen / élevé']]),hint:'JSON a des clés, mais le commentaire reste un texte libre. Une échelle ordonnée n’impose pas des distances égales.',questions:[
 Q('t5','Quelle source est semi-structurée ?',['Le JSON avec ses clés et son texte libre','La photographie seule','Le nombre d’entrées'],0,'Le JSON organise des champs sans imposer une table rigide ; son commentaire contient du langage libre.'),
 Q('t6','Quelle paire contient des médias non structurés ?',['A et E','B et C','A et F'],1,'Les pixels et le signal audio ne constituent pas des colonnes métier directement exploitables.'),
 Q('t7','Faible / moyen / élevé correspond à…',['Une catégorie ordonnée','Une quantité continue','Un identifiant'],0,'Il existe un ordre, mais pas de distance numérique mesurée entre les trois réponses.'),
 Q('t8','Compter les commentaires positifs nécessite d’abord…',['De calculer la moyenne des mots','De définir et appliquer une règle de codage','De changer le nom du fichier'],1,'Le codage transforme un contenu libre en catégories. La règle et les cas ambigus doivent être explicités.') ]},
 {title:'Choisir un calcul qui a du sens',intro:'La direction veut trois indicateurs. Sélectionnez une opération adaptée et identifiez ce que les données ne permettent pas de conclure.',evidence:()=>T(['Champ','Exemples'],[['Code postal','26000 ; 69000 ; 75000'],['Attente en minutes','4 ; 9 ; 12 ; 7'],['Atelier','Photo ; Son ; Photo ; Affiche'],['Note déclarée','1 ; 2 ; 4 ; 5 sur une échelle de satisfaction']]),hint:'Vérifiez ce que mesure la variable avant de choisir un calcul.',questions:[
 Q('t9','Pour décrire l’origine géographique, vous calculez…',['Le code postal moyen','Le nombre d’inscriptions par zone postale','La somme des codes'],1,'Un code postal est une étiquette géographique. Sa moyenne n’a pas de sens.'),
 Q('t10','Quelle est l’attente moyenne sur les quatre valeurs ?',['7 minutes','8 minutes','9 minutes'],1,'(4 + 9 + 12 + 7) / 4 = 8 minutes. Cette moyenne décrit seulement cet extrait.'),
 Q('t11','Quelle information montre la popularité des ateliers dans cet extrait ?',['Photo représente 2 inscriptions sur 4','La moyenne des noms vaut Photo','Photo attire nécessairement la moitié de tous les étudiants'],0,'La fréquence vaut 50 % dans l’extrait. Elle ne prouve pas la répartition dans toute la population.'),
 Q('t12','Pour une note de satisfaction de 1 à 5, quelle précaution est utile ?',['Supposer que 4 signifie deux fois plus satisfait que 2','Examiner aussi la distribution et l’ordre des réponses','Traiter les notes comme des identifiants sans ordre'],1,'Les notes codent une appréciation ordonnée. Une moyenne suppose un espacement interprétable et ne montre pas les avis opposés.') ]}
],
analytics:[
 {title:'Lire avant de conclure',intro:'Consultez les 12 groupes d’inscriptions ci-dessous. Choisissez l’indicateur, puis comparez des taux plutôt que les seuls effectifs.',evidence:sessionTable,hint:'Taux de présence = présents / inscrits. Additionnez les numérateurs et dénominateurs avant de calculer le taux global.',questions:[
 Q('a1','Combien d’inscriptions figure-t-il dans le bilan ?',['180','234','360'],2,'Photo : 160, Son : 120, Affiche : 80, soit 360 inscriptions.'),
 Q('a2','Quel est le taux global de présence ?',['65 %','75 %','85 %'],0,'234 présences pour 360 inscriptions : 234 / 360 = 65 %.'),
 Q('a3','Photo attire davantage de présents. Son taux est-il supérieur à celui de Son ?',['Oui','Non, les deux atteignent 65 %'],1,'Photo : 104/160. Son : 78/120. Les effectifs diffèrent, les taux sont identiques.'),
 Q('a4','Ce bilan relève d’abord de l’analyse…',['Descriptive','Prédictive','Prescriptive'],0,'On résume ce qui s’est passé. On ne prédit pas encore et on ne choisit pas une action.') ]},
 {title:'Du constat à l’hypothèse',intro:'Reprenez le même bilan. Les rappels semblent associés à la présence. Déterminez ce qui est établi et ce qui demande une enquête.',evidence:sessionTable,hint:'Un écart observé entre groupes ne dit pas automatiquement pourquoi cet écart existe.',questions:[
 Q('a5','Quel écart observe-t-on entre les groupes avec et sans rappel ?',['10 points : 70 % contre 60 %','10 personnes : 70 contre 60','Aucun écart'],0,'Avec rappel : 126/180 = 70 %. Sans rappel : 108/180 = 60 %. La différence est de 10 points de pourcentage.'),
 Q('a6','Peut-on affirmer que le rappel cause tout cet écart ?',['Oui, le tableau le démontre','Non, l’attribution des rappels n’est pas documentée'],1,'Les groupes peuvent différer par leur motivation ou d’autres caractéristiques. Une association ne suffit pas à établir une causalité.'),
 Q('a7','Quelle question est diagnostique ?',['Combien seront présents demain ?','Pourquoi les groupes du soir ont-ils un taux inférieur ?','Quel est le nombre total de présents ?'],1,'L’analyse diagnostique recherche des explications à un constat passé.'),
 Q('a8','Quel élément permettrait de renforcer l’enquête ?',['La couleur préférée des organisateurs','Les raisons d’absence et les conditions d’envoi des rappels','Un graphique plus grand'],1,'Ces informations permettraient de confronter les hypothèses au fonctionnement réel du dispositif.') ]},
 {title:'Décider sous contrainte',intro:'Vous disposez de 400 € pour recruter des inscrits. Déplacez le budget entre les deux canaux. Les rendements sont des hypothèses constantes de simulation, pas des résultats garantis.',widget:'budget',hint:'Il y a quatre lots de 100 €. Le partenaire fournit davantage de présents attendus par lot, mais sa capacité est limitée.',questions:[
 Q('a9','Sans contrainte de capacité, quel canal maximise les présents attendus ?',['Instagram : 10 inscrits / 100 €, présence 60 %','Partenaire : 8 inscrits / 100 €, présence 90 %'],1,'Un lot Instagram fournit 6 présents attendus ; un lot Partenaire, 7,2. Le nombre d’inscrits seul conduit à une autre conclusion.'),
 Q('a10','Le partenaire n’accepte que 200 €. Quelle allocation maximise l’attendu avec cette contrainte ?',['400 € Instagram','200 € chacun','400 € Partenaire'],1,'Deux lots par canal donnent 12 + 14,4 = 26,4 présents attendus. 400 € Partenaire viole la contrainte.'),
 Q('a11','La recherche d’une allocation sous contrainte relève de…',['L’analyse prescriptive','L’analyse uniquement descriptive','La collecte'],0,'On recommande une action en fonction d’un objectif, de contraintes et d’hypothèses.'),
 Q('a12','Avant d’appliquer cette allocation, que faut-il vérifier ?',['Que les rendements restent plausibles quand le budget change','Que l’attendu est forcément un entier','Que le canal le plus visible reçoit tout'],0,'La saturation, le ciblage et la période peuvent modifier les taux. L’attendu peut être décimal, même si le résultat réel sera entier.') ]}
],
lifecycle:[
 {title:'Reconstituer le parcours',intro:'Remettez les sept cartes dans l’ordre à l’aide des flèches. L’équipe doit pouvoir expliquer à quoi sert chaque étape. Le cycle peut ensuite être repris si une erreur apparaît.',widget:'order',hint:'Le besoin détermine la collecte ; les données sont préparées avant l’analyse et restituées avant la décision de conservation.',questions:[
 Q('l1','Que faut-il fixer avant de construire le formulaire ?',['Les indicateurs utiles à la question étudiée','La couleur des graphiques finaux','Le nom de l’algorithme'],0,'Le besoin permet de déterminer les données réellement nécessaires.'),
 Q('l2','Si une définition erronée apparaît après l’analyse, il faut…',['Revenir aux étapes concernées et recalculer','Conserver les chiffres déjà présentés','Tout effacer sans diagnostic'],0,'Le cycle est itératif : documenter, corriger et recalculer assure la traçabilité.') ]},
 {title:'Nettoyer sans inventer',intro:'Le fichier brut comporte un doublon confirmé, trois graphies du même canal et un prix manquant. Activez les traitements et observez leurs effets sur les chiffres.',widget:'clean',hint:'Un prix inconnu n’est pas zéro. Le doublon est confirmé ici par la source, pas seulement par une ressemblance.',questions:[
 Q('l3','Après retrait du doublon confirmé, combien d’inscriptions distinctes restent ?',['10','11','12'],1,'D02 est présent deux fois pour la même inscription ; 12 lignes donnent 11 inscriptions distinctes.'),
 Q('l4','Que faire du prix manquant de D06 ?',['Le remplacer par 0 €','Le laisser inconnu et signaler le périmètre du calcul','Lui attribuer le prix maximal'],1,'On ne connaît pas le montant. Le calcul peut être fait sur les montants connus, avec son dénominateur explicite.'),
 Q('l5','Après dédoublonnage, quelle moyenne des prix connus obtient-on ?',['16,20 € sur 11 inscriptions','17,40 € sur 10 prix connus','18 € sur 12 lignes'],1,'Les dix prix connus totalisent 174 €, soit 17,40 €. Le onzième prix reste inconnu.'),
 Q('l6','Normaliser Instagram, insta et IG permet…',['D’augmenter la recette','De regrouper une même catégorie sans changer les personnes','De prouver l’efficacité du canal'],1,'La normalisation répare le libellé. Elle ne modifie ni les inscriptions ni leur montant.') ]},
 {title:'Organiser le passage de relais',intro:'Trois équipes veulent accéder au dossier. Choisissez une organisation qui répond à leur besoin et évite les pertes d’information.',evidence:()=>T(['Demande','Besoin annoncé'],[['Accueil','Contrôler les entrées le jour du festival'],['Communication','Comparer la fréquentation des ateliers'],['Direction','Lire le bilan de la première édition'],['Prestataire','Recevoir une copie complète, sans justification']]),hint:'Reliez chaque accès à une tâche. Documentez les règles pour que le prochain analyste puisse comprendre le fichier.',questions:[
 Q('l7','Quel livrable suffit à la communication pour ce bilan ?',['Les noms et téléphones de tous les participants','Des totaux par atelier et les définitions des indicateurs','Tous les fichiers bruts sans explication'],1,'Un bilan agrégé répond au besoin décrit. Des coordonnées personnelles ne sont pas nécessaires à cette comparaison.'),
 Q('l8','Avant de transmettre un fichier préparé, il faut conserver…',['Une trace des transformations et la version source maîtrisée','Uniquement une capture du graphique','Aucune définition pour alléger le dossier'],0,'La traçabilité rend les résultats reproductibles et aide à retrouver une erreur.'),
 Q('l9','Après le festival, la conservation se décide…',['Selon un objectif documenté et une durée adaptée','Pour toujours par défaut','En fonction du nombre de couleurs du tableau'],0,'Le scénario appelle une règle de conservation liée au besoin, à faire valider par les personnes responsables.'),
 Q('l10','Un fichier a été partagé par erreur : quelle première réaction est cohérente ?',['Attendre le bilan annuel','Alerter le responsable, limiter l’accès et documenter l’incident','Renommer le fichier'],1,'La sécurisation et le signalement permettent une évaluation de l’incident ; renommer ne résout pas le partage.') ]}
],
science:[
 {title:'Construire une question testable',intro:'Le brief initial dit : « Utilisons la data pour faire un meilleur festival ». Transformez-le en protocole que l’on peut évaluer.',evidence:()=>T(['Information','Dossier'],[['Problème','Des inscrits ne viennent pas aux ateliers'],['Données disponibles','Inscriptions, présences, créneaux, rappels'],['Action possible','Tester un rappel avant l’atelier'],['Ressource','Une équipe et une édition pilote']]),hint:'Reliez objectif, indicateur, méthode et décision. Un outil n’est pas un objectif.',questions:[
 Q('s1','Quelle question est testable ?',['La data est-elle moderne ?','Un rappel améliore-t-il le taux de présence aux ateliers ?','Quel outil impressionne le plus ?'],1,'La question relie une action à un résultat observable.'),
 Q('s2','Quel indicateur correspond à cette question ?',['Présents / inscrits aux ateliers','Abonnés Instagram / photos','Nombre de colonnes du fichier'],0,'Ce taux mesure la participation parmi les inscriptions, contrairement à une audience sociale.'),
 Q('s3','Quelle variable est indispensable pour comparer des groupes ?',['La réception ou l’attribution du rappel, définie précisément','Le prénom du graphiste','La couleur de la scène'],0,'Il faut savoir quelle condition chaque observation représente. Attribuer et recevoir ne sont pas synonymes.'),
 Q('s4','Quelle démarche est cohérente ?',['Choisir un modèle puis chercher une question','Définir le besoin, préparer, analyser, valider et interpréter','Publier uniquement le meilleur résultat'],1,'Une démarche de Data Science relie ces étapes et peut revenir en arrière.') ]},
 {title:'Déjouer un résultat trompeur',intro:'Cette enquête fictive utilise un autre échantillon du festival. Comparez le bilan global puis les créneaux. Les groupes ne sont pas répartis de la même façon.',evidence:()=>T(['Créneau','Rappel','Inscrits','Présents','Taux'],[['Matin','Oui',80,64,'80 %'],['Matin','Non',20,18,'90 %'],['Soir','Oui',20,8,'40 %'],['Soir','Non',80,40,'50 %'],['Ensemble','Oui',100,72,'72 %'],['Ensemble','Non',100,58,'58 %']],'Échantillon B, distinct du bilan de Data Analytics'),hint:'Examinez les créneaux séparément avant de comparer les deux totaux.',questions:[
 Q('s5','Dans le total, le groupe avec rappel a…',['14 points de présence en plus','14 points en moins','Le même taux'],0,'72 % moins 58 % donne 14 points.'),
 Q('s6','À créneau identique, le groupe avec rappel a…',['Un meilleur taux dans les deux créneaux','Un taux inférieur de 10 points dans les deux créneaux','Un taux identique'],1,'Matin : 80 % contre 90 %. Soir : 40 % contre 50 %. La composition des groupes inverse la lecture globale.'),
 Q('s7','Quel diagnostic est défendable ?',['Le rappel est forcément bénéfique','Le rappel est forcément nocif','Le bilan global est confondu avec la répartition des créneaux'],2,'L’inversion montre une variable de composition importante. Ces observations seules ne prouvent ni bénéfice ni nuisance causale.'),
 Q('s8','Pour tester l’effet, quel protocole serait plus solide ?',['Attribuer aléatoirement le rappel à l’intérieur de chaque créneau, avec effectif suffisant','Choisir les plus motivés pour recevoir le rappel','Comparer seulement les totaux'],0,'La randomisation au sein des créneaux limite les différences systématiques ; l’incertitude devra encore être évaluée.') ]},
 {title:'Décider après un pilote',intro:'Un petit pilote répartit aléatoirement 40 inscriptions entre deux groupes comparables. Le résultat est encourageant, mais encore incertain.',evidence:()=>T(['Groupe','Inscrits','Présents'],[['Rappel',20,16],['Sans rappel',20,14]]),hint:'Deux personnes d’écart sur un petit pilote ne suffisent pas à promettre une hausse certaine.',questions:[
 Q('s9','L’écart observé vaut…',['2 points','10 points','20 points'],1,'16/20 = 80 %, 14/20 = 70 %, soit 10 points.'),
 Q('s10','Quelle conclusion retient-on ?',['Le pilote prouve définitivement un gain de 10 points','Le résultat suggère une piste à confirmer sur davantage de cas','Le rappel n’a aucun effet'],1,'Un petit échantillon donne un résultat instable. La taille et l’incertitude doivent être examinées.'),
 Q('s11','Quelle suite serait cohérente ?',['Étendre un test documenté et surveiller aussi coûts et désabonnements','Généraliser sans suivi','Supprimer les absents pour améliorer le taux'],0,'Une décision tient compte de l’efficacité, du coût et des effets indésirables.'),
 Q('s12','Que doit contenir le compte rendu ?',['Seulement le taux le plus favorable','Question, méthode, résultats, limites et proposition de suite','Uniquement le nom du logiciel'],1,'La direction doit pouvoir comprendre ce qui a été mesuré et la portée de la recommandation.') ]}
],
bigdata:[
 {title:'Repérer les contraintes',intro:'Déclic envisage un réseau de festivals. Associez chaque difficulté au V le plus directement concerné. Plusieurs dimensions peuvent interagir.',evidence:()=>T(['Signal','Constat'],[['Archives','40 téraoctets de médias à conserver'],['Entrées','Alertes attendues en moins de deux secondes'],['Sources','Tables, sons, vidéos et messages'],['Qualité','Des capteurs envoient des mesures en double'],['Décision','Les organisateurs ne savent pas quel usage donner aux données']]),hint:'Distinguez la quantité, la rapidité, les formats, la fiabilité et l’utilité.',questions:[
 ...['Volume','Vélocité','Variété','Véracité','Valeur'].map((v,i)=>Q('b'+i,['40 To d’archives : quelle contrainte ?','Une alerte en deux secondes : quelle contrainte ?','Tables, audio et vidéos : quelle contrainte ?','Des mesures dupliquées : quelle contrainte ?','Des données sans usage défini : quelle contrainte ?'][i],['Volume','Vélocité','Variété','Véracité','Valeur'],i,['La quantité stockée pose ici la question du volume.','La rapidité de production et de traitement est centrale.','La diversité des formats nécessite plusieurs traitements.','La fiabilité des données est en cause.','La valeur dépend d’un usage utile à une décision.'][i])) ]},
 {title:'Faire varier l’échelle',intro:'Sélectionnez les trois profils et observez le débit, le stockage quotidien et l’objectif de traitement. Le calcul utilise des kilo-octets et gigaoctets décimaux. Les profils sont des hypothèses pédagogiques.',widget:'flow',hint:'Une ligne peut être légère ou très lourde. La fréquence et le délai attendu changent le problème.',questions:[
 Q('b5','Le profil « Direct multisite » produit…',['Environ 86,4 Go par jour','2 Mo par jour','500 lignes par an'],0,'500 événements/s × 2 ko × 86 400 secondes = 86 400 000 ko = 86,4 Go/jour.'),
 Q('b6','L’archive de deux millions de lignes légères impose-t-elle à elle seule une infrastructure distribuée ?',['Oui, toujours au-delà d’un million','Non, cela dépend du traitement et des moyens'],1,'Dans ce profil, 200 Mo reçus une fois par an ne constituent pas automatiquement un problème Big Data.'),
 Q('b7','Que change le profil vidéo par rapport aux événements légers ?',['Seulement le nombre de lignes','Le poids de chaque événement et les traitements nécessaires','Rien si les fichiers sont nommés'],1,'Le nombre de lignes ne décrit pas la taille ni le coût d’analyse des médias.'),
 Q('b8','Quelle erreur faut-il éviter ?',['Choisir une solution après avoir mesuré les besoins','Déclarer “Big Data” à partir du seul nombre de lignes','Vérifier le délai acceptable'],1,'Big Data décrit des contraintes à traiter, pas un label obtenu au franchissement d’un nombre magique.') ]},
 {title:'Dimensionner une réponse utile',intro:'L’équipe propose trois besoins. Choisissez un dispositif proportionné plutôt qu’une solution identique pour tous.',evidence:()=>T(['Besoin','Contrainte'],[['Bilan annuel','Un CSV léger, résultat attendu la semaine suivante'],['Alerte d’affluence','Flux de capteurs, réaction rapide'],['Archive vidéo','Gros fichiers, analyse différée'],['Mesures douteuses','Capteurs en double, horloges décalées']]),hint:'Temps réel, traitement différé et contrôle qualité répondent à des besoins différents.',questions:[
 Q('b9','Pour le bilan annuel léger, quel choix est raisonnable ?',['Tableur ou base simple avec contrôles','Cluster distribué obligatoire','Aucun calcul possible'],0,'Une solution simple peut suffire si elle satisfait le besoin et les volumes constatés.'),
 Q('b10','Pour l’alerte d’affluence, la priorité est…',['Un traitement du flux avec contrôle du délai et des erreurs','Une exportation annuelle','La compression du logo'],0,'La valeur de l’alerte dépend de sa disponibilité à temps et de la fiabilité du signal.'),
 Q('b11','Pour les vidéos sans urgence, quelle approche est plausible ?',['Un traitement différé des fichiers avec ressources adaptées','Analyser chaque image instantanément par principe','Réduire toute vidéo à une cellule texte'],0,'Le traitement par lots peut répondre au besoin sans imposer du temps réel.'),
 Q('b12','Ajouter de la puissance à des capteurs qui dupliquent les mesures…',['Corrige automatiquement la qualité','Peut traiter plus vite des données toujours erronées','Supprime le besoin de définitions'],1,'La qualité doit être contrôlée à la source et lors de la préparation.') ]}
],
ml:[
 {title:'Séparer sans fuite',intro:'Le modèle doit estimer l’absence à partir d’informations disponibles avant l’atelier. Affectez les six groupes de participants : quatre à l’apprentissage, un à la validation et un au test. Deux lignes d’une même personne restent ensemble.',widget:'split',hint:'Apprentissage : ajuster le modèle. Validation : choisir les réglages. Test : évaluer une fois les choix figés.',questions:[
 Q('m1','Quelle cible veut-on prédire ?',['Le nom du canal','L’absence à l’atelier','Le numéro de ligne'],1,'La cible est le résultat futur à estimer, ici absence ou présence.'),
 Q('m2','Quelle variable provoque une fuite si elle sert à prévoir l’absence ?',['Le canal connu à l’inscription','Le délai entre inscription et atelier','L’heure de badgeage réellement observée le jour de l’atelier'],2,'Le badgeage révèle un événement postérieur à la prédiction. Le modèle bénéficierait d’une information indisponible au moment d’agir.'),
 Q('m3','Pourquoi conserver toutes les lignes d’une personne dans le même lot ?',['Pour éviter qu’elle soit à la fois apprise et évaluée','Pour obtenir trois lots de même couleur','Pour réduire le nombre de colonnes'],0,'Une évaluation sur une personne déjà vue peut surestimer la généralisation à de nouvelles personnes.') ]},
 {title:'Mesurer les erreurs',intro:'Un modèle fictif fournit un score de risque pour 20 cas de validation. Faites varier le seuil. Une alerte est émise si le score atteint ou dépasse le seuil. Les quatre compteurs sont recalculés à partir des lignes affichées.',widget:'threshold',hint:'Une fausse alerte vise une personne finalement présente. Une absence manquée est une personne absente sans alerte.',questions:[
 Q('m4','Au seuil de 50 %, combien de fausses alertes observe-t-on ?',['2','4','8'],1,'Dix alertes sont émises : six absences détectées et quatre personnes finalement présentes.'),
 Q('m5','Au seuil de 50 %, combien d’absences sont manquées ?',['2','6','10'],0,'Il y a huit absences observées, dont six détectées. Deux restent sous le seuil.'),
 Q('m6','Quand on baisse le seuil, on tend à…',['Émettre moins d’alertes','Détecter davantage d’absences, au prix de fausses alertes possibles','Supprimer toutes les erreurs'],1,'Abaisser le seuil inclut davantage de cas. Il faut examiner le compromis entre les erreurs.'),
 Q('m7','Après choix du seuil sur ces cas, où évaluer la performance finale ?',['Sur ces mêmes cas, sans réserve','Sur le lot de test resté à l’écart des réglages','Sur les seuls cas faciles'],1,'La validation sert aux réglages. Le test indépendant sert à estimer la performance après ces choix.') ]},
 {title:'Comparer au point de départ',intro:'Sur un autre jeu de test de 100 inscriptions, seules 10 personnes sont absentes. Une règle naïve prédit que tout le monde sera présent. Le modèle émet 20 alertes : 8 visent des absents et 12 des présents.',evidence:()=>T(['Approche','Absences détectées','Fausses alertes','Absences manquées','Présences reconnues'],[['Tout le monde présent',0,0,10,90],['Modèle',8,12,2,78]],'Jeu de test C : 100 inscriptions, distinct des 20 cas de validation'),hint:'Le taux de bonnes réponses global peut masquer l’échec sur le groupe minoritaire.',questions:[
 Q('m8','La règle naïve obtient 90 % de bonnes réponses. Est-elle utile pour repérer les absences ?',['Oui, 90 % suffit','Non, elle ne repère aucune absence'],1,'Elle reconnaît 90 présences mais rate les dix absences : son rappel sur les absences est nul.'),
 Q('m9','Quelle part des absences le modèle détecte-t-il ?',['40 %','80 %','86 %'],1,'Le rappel sur les absences vaut 8/10 = 80 %.'),
 Q('m10','Quelle part des alertes du modèle correspond à une absence ?',['40 %','80 %','90 %'],0,'La précision des alertes vaut 8/20 = 40 %. Il faut donc prévoir le coût des fausses alertes.'),
 Q('m11','Quelle action est la plus défendable avec ce modèle ?',['Annuler automatiquement tous les billets signalés','Tester un rappel peu intrusif avec suivi humain et mesure de l’utilité','Déclarer toute personne signalée absente avec certitude'],1,'Un score est incertain. Le coût de l’action, les erreurs et les effets sur les participants doivent être pris en compte.') ]}
],
dl:[
 {title:'Choisir une méthode proportionnée',intro:'Les organisateurs veulent tout traiter avec un réseau profond. Examinez chaque besoin, les données disponibles et l’existence d’alternatives.',evidence:()=>T(['Besoin','Ressource'],[['Total des ventes','Une colonne de prix'],['Tri des scènes dans les photos','50 000 images, modèle préentraîné disponible'],['Réduction étudiant','Règle tarifaire explicite'],['Lecture des commentaires','20 commentaires courts'],['Transcription audio','Des heures d’enregistrements, outil préentraîné à évaluer']]),hint:'Deep Learning désigne des réseaux profonds. Il peut être pertinent pour des médias, mais ce n’est pas une obligation liée au format.',questions:[
 Q('d1','Pour totaliser les ventes, il faut d’abord…',['Une somme contrôlée','Un réseau de neurones profond','Un modèle génératif'],0,'L’opération est définie et les données structurées : une somme suffit.'),
 Q('d2','Pour les 50 000 photos, quel point de départ est plausible ?',['Entraîner obligatoirement depuis zéro','Évaluer un modèle préentraîné sur des images du festival','Promettre 100 % de réussite sans essai'],1,'Un modèle préentraîné peut être adapté ou utilisé, mais doit être évalué dans le contexte réel.'),
 Q('d3','Pour les 20 commentaires, une lecture humaine codée est…',['Impossible car le texte est non structuré','Une option raisonnable, avec règles et cas ambigus','Toujours moins fiable qu’une IA'],1,'La petite quantité permet une lecture humaine. Le choix dépend du besoin et des ressources, pas seulement du format.'),
 Q('d4','Le Deep Learning appartient…',['Au Machine Learning, lui-même dans l’IA','À un domaine sans rapport avec l’IA','À toutes les formules de tableur'],0,'Les réseaux profonds sont une famille de modèles d’apprentissage automatique.') ]},
 {title:'Évaluer hors des images faciles',intro:'Un classificateur de scènes est testé sur 100 photos étiquetées manuellement. Comparez les vues de jour et de nuit. Le total seul masque une difficulté.',widget:'vision',hint:'Examinez les réussites et les erreurs dans chaque sous-ensemble.',questions:[
 Q('d5','Quel est le taux de réussite global ?',['50 %','81 %','90 %'],1,'72 réussites de jour + 9 de nuit = 81 réussites sur 100 photos.'),
 Q('d6','Sur les photos de nuit, le taux atteint…',['45 %','81 %','90 %'],0,'9 réussites sur 20 photos de nuit = 45 %.'),
 Q('d7','Quel risque apparaît si le festival suivant se déroule surtout la nuit ?',['Le taux global restera forcément 81 %','La performance peut chuter avec la nouvelle répartition','Les erreurs disparaîtront'],1,'Le contexte d’usage change. La moyenne historique ne garantit pas la performance sur une autre distribution.'),
 Q('d8','Quelle suite est pertinente ?',['Retirer les photos de nuit du bilan','Examiner les erreurs, enrichir les exemples adaptés et évaluer à nouveau sur un lot indépendant','Agrandir le logo du modèle'],1,'Il faut comprendre le défaut et tester une amélioration sur des cas non utilisés pour la préparer.') ]},
 {title:'Constituer un jeu fiable',intro:'Vous préparez les données pour un nouveau modèle. Le dossier contient des rafales presque identiques et des photos ambiguës : une même image peut montrer scène et public.',evidence:()=>T(['Lot','Problème'],[['Rafale A','30 photos quasi identiques prises à la même seconde'],['Photo B','Scène et public dans le même cadre'],['Photo C','Visage reconnaissable, usage non vérifié'],['Lot D','Photos nocturnes encore peu nombreuses']]),hint:'La qualité du jeu, des annotations et de la séparation compte autant que le modèle.',questions:[
 Q('d9','Comment répartir une rafale entre apprentissage et test ?',['La mélanger au hasard image par image','Garder la rafale dans le même lot','Copier la rafale dans tous les lots'],1,'Des quasi-doublons entre lots permettent une évaluation trop facile.'),
 Q('d10','Pour les photos ambiguës, que faut-il prévoir ?',['Une règle d’annotation explicite, éventuellement plusieurs étiquettes','Une réponse improvisée par chaque annotateur','Supprimer toute photo sans justification'],0,'Une convention partagée et un traitement des désaccords rendent les étiquettes interprétables.'),
 Q('d11','Un score de confiance de 0,95 signifie-t-il que le résultat est certain ?',['Oui','Non, le modèle peut être très confiant et se tromper'],1,'La confiance n’est pas une garantie ni, sans calibration, une probabilité fiable de réussite.'),
 Q('d12','Avant d’exploiter les photos, quelle vérification complète le travail technique ?',['Le cadre d’usage, les droits et les accès','Le nombre de couleurs de la page uniquement','Aucune si le fichier est public'],0,'L’accessibilité d’une image ne suffit pas à établir tous les usages possibles. Le responsable doit valider le cadre du projet.') ]}
],
ai:[
 {title:'Relier le besoin à la solution',intro:'L’équipe emploie le mot IA pour cinq projets différents. Choisissez le mécanisme le plus précis proposé. Les familles se recoupent : un modèle génératif peut aussi utiliser du Deep Learning.',evidence:()=>T(['Projet','Fonctionnement annoncé'],[['Rappel','Envoi 24 h avant l’atelier selon une règle fixe'],['Bilan','Somme des ventes par canal'],['Risque','Score appris à partir d’exemples historiques'],['Photos','Reconnaissance par réseau de neurones profond'],['Rédaction','Production de nouvelles variantes de texte']]),hint:'Le mécanisme compte : calcul explicite, règle, apprentissage, réseau profond ou génération.',questions:[
 ...['Automatisation par règle','Data Analytics','Machine Learning','Deep Learning','IA générative'].map((v,i)=>Q('i'+i,['Envoi fixe à J-1','Somme des ventes par canal','Score appris sur des exemples','Reconnaissance par réseau profond','Création de variantes de texte'][i],['Automatisation par règle','Data Analytics','Machine Learning','Deep Learning','IA générative'],i,['Une règle temporelle suffit ; toute automatisation n’est pas de l’IA.','Il s’agit d’une agrégation descriptive.','Le score est appris à partir de données.','Le réseau profond est une famille précise de Machine Learning.','L’objectif est de produire du contenu nouveau ; le modèle peut reposer sur du Deep Learning.'][i])) ]},
 {title:'Auditer une réponse générée',intro:'Comparez le texte produit à la fiche validée. Pour chaque affirmation, indiquez si elle est confirmée, contredite ou absente des sources.',evidence:()=>`<div class="source-pair"><article><h4>Fiche validée par l’organisation</h4><p>Déclic : samedi 12 juin 2027, de 14 h à 22 h. Entrée : 12 €. Atelier photo : inscription préalable obligatoire. Programme musical encore en cours de validation.</p></article><article><h4>Proposition générée, à vérifier</h4><p>« Retrouvez Déclic samedi 12 juin 2027 ! L’entrée est gratuite. Venez à l’atelier photo sans réservation. Trois concerts sont confirmés. Le festival ferme à 22 h. »</p></article></div>`,hint:'Une phrase peut être plausible sans être appuyée par la fiche. Ne confondez pas absence de preuve et contradiction explicite.',questions:[
 Q('i5','« Samedi 12 juin 2027 »',['Confirmé','Contredit','Non documenté'],0,'La date figure explicitement dans la fiche validée.'),
 Q('i6','« L’entrée est gratuite »',['Confirmé','Contredit','Non documenté'],1,'La fiche annonce 12 €. Il faut corriger le texte.'),
 Q('i7','« Atelier photo sans réservation »',['Confirmé','Contredit','Non documenté'],1,'L’inscription préalable est obligatoire selon la source.'),
 Q('i8','« Trois concerts sont confirmés »',['Confirmé','Contredit','Non documenté'],2,'La source ne donne ni ce nombre ni une confirmation. Il ne faut pas publier cette affirmation sans validation.'),
 Q('i9','« Le festival ferme à 22 h »',['Confirmé','Contredit','Non documenté'],0,'L’heure de fermeture correspond à la fiche.') ]},
 {title:'Définir un usage encadré',intro:'Vous devez recommander un mode d’emploi à l’équipe communication. Choisissez les éléments d’une consigne et d’un circuit de validation adaptés au dossier précédent.',evidence:()=>T(['Contrôle','Responsable'],[['Faits pratiques','Organisation'],['Ton et lisibilité','Communication'],['Validation avant publication','Personne désignée'],['Données fournies à l’outil','Uniquement celles utiles à la tâche']]),hint:'Une bonne consigne cadre les sources et l’incertitude ; elle ne dispense pas de vérifier la sortie.',questions:[
 Q('i10','Quelle consigne est la plus exploitable ?',['Rédigez quelque chose d’impressionnant','À partir de la fiche validée, proposez trois textes de 60 mots ; n’ajoutez aucun fait et signalez les informations manquantes','Inventez un programme crédible'],1,'La tâche, les sources, le format et le traitement des manques sont explicités.'),
 Q('i11','Que transmettre pour rédiger cette annonce ?',['La fiche pratique validée','La liste complète des coordonnées des inscrits','Les conversations privées des participants'],0,'La rédaction de l’annonce n’a pas besoin de coordonnées ou de conversations privées.'),
 Q('i12','Comment organiser la publication ?',['Publication automatique dès que le texte paraît fluide','Vérification des faits et validation humaine avant diffusion','Validation par le nombre de mots seulement'],1,'La fluidité du texte ne garantit ni sa véracité ni son adéquation.'),
 Q('i13','Quel bilan justifie de conserver cet usage ?',['Le temps gagné seul','Le temps gagné, les corrections nécessaires et la qualité finale','Le nombre de variantes produites seul'],1,'L’utilité se mesure par le résultat et le coût du contrôle, pas uniquement par la vitesse de génération.') ]}
]
};

const key=()=>`${state.current}:${steps[state.current]||0}`;
const currentStage=()=>workshop[state.current][steps[state.current]||0];
const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pct=(n,d)=>`${Math.round(n/d*100)} %`;
function refreshProgress(){
 for(const s of sections){const n=[0,1,2].filter(i=>validated.has(`${s.id}:${i}`)).length;if(n===3)state.done.add(s.id);else state.done.delete(s.id);}
 syncNav();
 if(workshop[state.current])$('#lab-status').textContent=`${[0,1,2].filter(i=>validated.has(`${state.current}:${i}`)).length} / 3 étapes validées`;
}
function invalidate(){validated.delete(key());checked[key()]=false;$('#feedback-zone').hidden=true;refreshProgress();document.querySelectorAll('.question-result').forEach(x=>x.hidden=true);$('#workshop-nav [aria-current] b').textContent=(steps[state.current]||0)+1;}
function analyticsDownloads(index){const csv=index===2?'declic-analytics-budget.csv':'declic-analytics-bilan.csv';return `<aside class="analytics-downloads" aria-label="Fichiers de travail"><h4>À vous de manipuler les données</h4><p>Téléchargez le classeur et ouvrez l’onglet <strong>${index===2?'Budget':'Bilan'}</strong> dans Excel, LibreOffice Calc ou Google Sheets. Effectuez vos calculs dans votre copie, puis répondez aux questions ci-dessous.</p><div class="download-actions"><a class="primary" href="downloads/declic-data-analytics.xlsx" download>Télécharger le classeur Excel (.xlsx)</a><a class="ghost" href="downloads/${csv}" download>Télécharger les données de cette activité (.csv)</a></div><p class="download-note">Les fichiers contiennent les mêmes données fictives que le site, sans corrigé. CSV : UTF-8, séparateur point-virgule.</p></aside>`;}
function render(s){
 const index=steps[s.id]||0,stage=workshop[s.id][index];
 $('#hint-btn').hidden=false;$('#check-btn').hidden=false;$('#next-btn').hidden=false;
 $('#next-btn').textContent=index<2?'Étape suivante':'Notion suivante';
 $('#workshop-nav').innerHTML=`<nav class="step-nav" aria-label="Étapes du laboratoire">${workshop[s.id].map((x,i)=>`<button type="button" data-step="${i}" ${i===index?'aria-current="step"':''}><b>${validated.has(`${s.id}:${i}`)?'✓':i+1}</b><span>${x.title}</span></button>`).join('')}</nav><p class="step-note">Chaque étape est accessible librement. Validez les trois étapes pour terminer ce laboratoire.</p>`;
 $('#lab-content').innerHTML=`<span class="eyebrow">Activité ${index+1} sur 3</span><h3 class="activity-title">${stage.title}</h3><p class="instruction">${stage.intro}</p>${s.id==='analytics'?analyticsDownloads(index):''}${stage.evidence?stage.evidence():''}${stage.widget?`<div class="experiment" id="experiment"></div>`:''}<div class="questions-list">${stage.questions.map((q,n)=>`<fieldset class="question" id="question-${q.id}"><legend><span>${n+1}.</span> ${q.text}</legend><div class="answer-options">${q.options.map((o,i)=>`<label><input type="radio" name="${q.id}" value="${i}" ${responses[q.id]===i?'checked':''}><span>${o}</span></label>`).join('')}</div><p class="question-result" hidden></p></fieldset>`).join('')}</div>`;
 if(stage.widget)drawWidget(stage.widget);
 $('#lab-content').querySelectorAll('input[type=radio]').forEach(el=>el.addEventListener('change',()=>{responses[el.name]=Number(el.value);invalidate();}));
 $('#workshop-nav').querySelectorAll('[data-step]').forEach(el=>el.addEventListener('click',()=>openStep(Number(el.dataset.step))));
 refreshProgress();
 if(checked[key()])checkStage(false);
}
function openStep(i){steps[state.current]=i;$('#feedback-zone').hidden=true;render(sections.find(s=>s.id===state.current));$('#workshop-nav').scrollIntoView({block:'start',behavior:'smooth'});}
function checkStage(scroll=true){
 const stage=currentStage(),unanswered=stage.questions.filter(q=>responses[q.id]===undefined);
 const f=$('#feedback-zone');f.hidden=false;f.className='feedback-zone';
 if(unanswered.length){f.innerHTML=`<strong>${unanswered.length} réponse${unanswered.length>1?'s':''} à compléter</strong><p>Faites un choix pour chaque question avant d’afficher la correction.</p>`;if(scroll)document.getElementById(`question-${unanswered[0].id}`).scrollIntoView({block:'center',behavior:'smooth'});return;}
 let ok=0,total=stage.questions.length;
 for(const q of stage.questions){const right=responses[q.id]===q.answer;if(right)ok++;const result=$(`#question-${q.id} .question-result`);result.hidden=false;result.className='question-result '+(right?'right':'wrong');result.innerHTML=`<strong>${right?'Choix correct':'À revoir'}.</strong> ${q.why}`;}
 let special='';
 if(stage.widget==='order'){total++;const good=state.stageOrder.join('|')==='Définir le besoin|Collecter|Stocker|Préparer|Analyser|Restituer|Conserver ou supprimer';if(good)ok++;special=good?'Le parcours est remis en ordre.':'Ordre à reprendre : définir le besoin, collecter, stocker, préparer, analyser, restituer, conserver ou supprimer. Les contrôles accompagnent toutes les étapes.';}
 if(stage.widget==='split'){total++;const values=Object.values(toolsState.groups);const good=values.filter(x=>x==='Apprentissage').length===4&&values.filter(x=>x==='Validation').length===1&&values.filter(x=>x==='Test').length===1;if(good)ok++;special=good?'Les six groupes sont affectés, sans partage d’une même personne entre lots.':'Affectez les six groupes : quatre à l’apprentissage, un à la validation, un au test. La règle porte sur les groupes, pas sur un partage aléatoire de leurs lignes.';}
 checked[key()]=true;
 if(ok===total)validated.add(key());else validated.delete(key());
 refreshProgress();
 f.classList.toggle('success',ok===total);
 f.innerHTML=`<strong>${ok===total?'Étape validée':`${ok} réponse${ok>1?'s':''} correcte${ok>1?'s':''} sur ${total}`}</strong><p>${special} ${ok===total?'Vous pouvez passer à la suite ou revenir sur vos choix.':'Lisez les explications sous chaque question, modifiez vos choix, puis vérifiez à nouveau.'}</p>`;
 $('#workshop-nav [aria-current]').querySelector('b').textContent=validated.has(key())?'✓':(steps[state.current]||0)+1;
 if(scroll)f.scrollIntoView({block:'nearest',behavior:'smooth'});
}
function drawWidget(type){
 const box=$('#experiment');
 if(type==='registry'){
  const selected=toolsState.filter,rows=records.filter(r=>selected==='Tous'||r.atelier===selected);
  box.innerHTML=`<div class="tool-row"><label>Atelier <select id="registry-filter">${['Tous','Photo','Son','Affiche'].map(v=>`<option ${selected===v?'selected':''}>${v}</option>`).join('')}</select></label><button type="button" class="ghost" id="download-registry">Télécharger les 48 inscriptions (CSV)</button><span>${rows.length} lignes visibles</span></div>${T(['Inscription','Atelier','Canal','Prix (€)','Présence','Attente (min)'],rows.map(r=>Object.values(r)),'Registre A : 48 inscriptions synthétiques, distinct du bilan agrégé des 360 inscriptions')}`;
  $('#registry-filter').addEventListener('change',e=>{toolsState.filter=e.target.value;drawWidget(type);});
  $('#download-registry').addEventListener('click',()=>{const csv='\uFEFF'+['inscription;atelier;canal;prix;presence;attente_minutes',...records.map(r=>Object.values(r).join(';'))].join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='declic-registre-a-48-inscriptions.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});
 }
 if(type==='clean'){
  const v=toolsState.clean;let rows=rawRows.map(r=>r.slice());if(v.dedup)rows=rows.filter((r,i,a)=>a.findIndex(x=>x[0]===r[0])===i);if(v.channel)rows=rows.map(r=>[r[0],['insta','IG'].includes(r[1])?'Instagram':r[1],r[2]]);
  const known=rows.filter(r=>r[2]!==null),sum=known.reduce((s,r)=>s+r[2],0),denom=v.missing?known.length:rows.length;
  box.innerHTML=`<div class="toggle-tools">${[['dedup','Retirer le doublon confirmé D02'],['channel','Uniformiser le canal Instagram'],['missing','Calculer la moyenne uniquement sur les prix connus']].map(([id,label])=>`<label><input type="checkbox" data-clean="${id}" ${v[id]?'checked':''}> ${label}</label>`).join('')}</div><div class="live-metrics"><p><b>${rows.length}</b> lignes</p><p><b>${known.length}</b> prix connus</p><p><b>${(sum/denom).toFixed(2).replace('.',',')} €</b> moyenne ${v.missing?'sur les prix connus':'naïve : prix inconnu compté comme 0'}</p></div>${T(['Inscription','Canal','Prix (€)'],rows.map(r=>[r[0],r[1],r[2]===null?'Inconnu':r[2]]),'Extrait brut C : anomalies introduites pour cet exercice')}`;
  box.querySelectorAll('[data-clean]').forEach(el=>el.addEventListener('change',()=>{v[el.dataset.clean]=el.checked;drawWidget(type);}));
 }
 if(type==='order'){
  box.innerHTML=`<div class="sequence">${state.stageOrder.map((x,i)=>`<div class="stage"><b>${i+1}</b><span>${x}</span><span class="move-group"><button data-move="${i}" data-dir="-1" ${i===0?'disabled':''} aria-label="Monter ${x}">↑</button><button data-move="${i}" data-dir="1" ${i===6?'disabled':''} aria-label="Descendre ${x}">↓</button></span></div>`).join('')}</div>`;
  box.querySelectorAll('[data-move]').forEach(b=>b.addEventListener('click',()=>{const i=Number(b.dataset.move),j=i+Number(b.dataset.dir);[state.stageOrder[i],state.stageOrder[j]]=[state.stageOrder[j],state.stageOrder[i]];invalidate();drawWidget(type);}));
 }
 if(type==='budget'){
  box.innerHTML=`${T(['Canal','Prix d’un lot','Inscrits attendus / lot','Taux de présence supposé','Plafond du partenaire'],[['Instagram','100 €',10,'60 %','Sans objet'],['Partenaire','100 €',8,'90 %','200 €']])}<label class="slider-label" for="budget-range">Budget Partenaire : <output id="budget-label"></output></label><input id="budget-range" type="range" min="0" max="4" step="1" value="${toolsState.budget}"><div id="budget-result" class="live-metrics" aria-live="polite"></div>`;
  const update=()=>{const n=toolsState.budget;$('#budget-label').textContent=`${n*100} € (Instagram : ${(4-n)*100} €)`;$('#budget-result').innerHTML=`<p><b>${(4-n)*10+n*8}</b> inscriptions attendues</p><p><b>${((4-n)*6+n*7.2).toFixed(1).replace('.',',')}</b> présences attendues</p><p><b>${n>2?'Hors contrainte':'Allocation admissible'}</b>${n>2?'Le partenaire accepte au maximum 200 €.':'Le plafond du partenaire est respecté.'}</p>`;};
  $('#budget-range').addEventListener('input',e=>{toolsState.budget=Number(e.target.value);update();});update();
 }
 if(type==='flow'){
  const profiles={bilan:{name:'Archive annuelle',count:2000000,size:.1,unit:'une fois par an',delay:'Bilan disponible la semaine suivante',rate:false},direct:{name:'Direct multisite',count:500,size:2,unit:'par seconde',delay:'Alerte en moins de 2 secondes',rate:true},video:{name:'Captures vidéo',count:20,size:500,unit:'par seconde',delay:'Analyse différée dans la journée',rate:true}};
  const p=profiles[toolsState.flow];
  box.innerHTML=`<div class="tool-row"><label>Profil <select id="flow-profile">${Object.entries(profiles).map(([k,v])=>`<option value="${k}" ${toolsState.flow===k?'selected':''}>${v.name}</option>`).join('')}</select></label></div><div class="live-metrics"><p><b>${p.count.toLocaleString('fr-FR')}</b> événements ${p.unit}</p><p><b>${p.size} ko</b> par événement</p><p><b>${p.rate?(p.count*p.size*86400/1000000).toLocaleString('fr-FR')+' Go/jour':p.count*p.size/1000+' Mo/an'}</b> volume calculé</p></div><p><strong>Objectif :</strong> ${p.delay}.</p><p class="instruction">Calcul simplifié sans compression ni réplication. Pour un flux continu : événements/s × ko/événement × 86 400 secondes.</p>`;
  $('#flow-profile').addEventListener('change',e=>{toolsState.flow=e.target.value;drawWidget(type);});
 }
 if(type==='split'){
  box.innerHTML=T(['Participant','Lignes associées','Lot à attribuer'],Array.from({length:6},(_,i)=>{const id=`P${i+1}`;return [id,`${id}-A et ${id}-B`,`<select aria-label="Lot du participant ${id}" data-group="${id}"><option value="">Choisir</option>${['Apprentissage','Validation','Test'].map(x=>`<option ${toolsState.groups[id]===x?'selected':''}>${x}</option>`).join('')}</select>`];}),'Miniature pédagogique : six participants, deux inscriptions chacun. Un vrai projet exige davantage de cas.');
  box.querySelectorAll('[data-group]').forEach(el=>el.addEventListener('change',()=>{toolsState.groups[el.dataset.group]=el.value;invalidate();}));
 }
 if(type==='threshold'){
  box.innerHTML=`<label class="slider-label" for="threshold-range">Seuil d’alerte : <output id="threshold-label"></output></label><input id="threshold-range" type="range" min="10" max="90" step="5" value="${toolsState.threshold}"><div id="matrix-live" class="live-metrics" aria-live="polite"></div><div id="prediction-table"></div>`;
  const update=()=>{const threshold=toolsState.threshold/100;let tp=0,fp=0,fn=0,tn=0;for(const r of predictionRows){if(r.score>=threshold){if(r.absent)tp++;else fp++;}else if(r.absent)fn++;else tn++;}$('#threshold-label').textContent=`${toolsState.threshold} %`;$('#matrix-live').innerHTML=[['Absences détectées',tp],['Fausses alertes',fp],['Absences manquées',fn],['Présences reconnues',tn]].map(([label,n])=>`<p><b>${n}</b>${label}</p>`).join('');$('#prediction-table').innerHTML=T(['Cas','Score de risque','Résultat observé','Décision au seuil actuel'],predictionRows.map(r=>[r.id,pct(r.score,1),r.absent?'Absent':'Présent',r.score>=threshold?'Alerte':'Pas d’alerte']),'20 cas de validation : scores inventés, pas un modèle entraîné dans le navigateur');};
  $('#threshold-range').addEventListener('input',e=>{toolsState.threshold=Number(e.target.value);update();});update();
 }
 if(type==='vision'){
  const subsets={jour:[80,72],nuit:[20,9],ensemble:[100,81]},[n,ok]=subsets[toolsState.subset];
  box.innerHTML=`<label>Photos à examiner <select id="vision-subset">${Object.keys(subsets).map(x=>`<option ${x===toolsState.subset?'selected':''}>${x}</option>`).join('')}</select></label><div class="live-metrics"><p><b>${n}</b> photos</p><p><b>${ok}</b> classements corrects</p><p><b>${n-ok}</b> erreurs</p><p><b>${pct(ok,n)}</b> réussite</p></div><div class="result-bar" role="img" aria-label="${pct(ok,n)} de réussite"><span style="width:${ok/n*100}%"></span></div><p class="instruction">Évaluation fictive d’un classificateur de scènes. Les étiquettes de référence sont données par des annotateurs humains.</p>`;
  $('#vision-subset').addEventListener('change',e=>{toolsState.subset=e.target.value;drawWidget(type);});
 }
}
$('#check-btn').addEventListener('click',()=>checkStage());
$('#hint-btn').addEventListener('click',()=>{const f=$('#feedback-zone');f.hidden=false;f.className='feedback-zone';f.innerHTML=`<strong>Une piste pour raisonner</strong><p>${currentStage().hint}</p>`;f.scrollIntoView({block:'nearest',behavior:'smooth'});});
$('#next-btn').addEventListener('click',()=>{const i=steps[state.current]||0;if(i<2)openStep(i+1);else{const s=sections.findIndex(s=>s.id===state.current);if(s<7)showLab(sections[s+1].id);else showHome();}});
window.addEventListener('hashchange',()=>{const id=location.hash.slice(1);if(id==='contexte')showContext();else if(workshop[id])showLab(id);else if(id!=='activity')showHome();});
const initial=location.hash.slice(1);if(initial==='contexte')showContext();else if(workshop[initial])showLab(initial);else syncNav();
